var graph = { 0: [1, 2], 1: [0, 3], 2: [0, 3, 4], 3: [1, 2], 4: [2] };

function bfs(start) {
  var visited = {};
  var queue = [start];
  var order = [];
  visited[start] = true;
  while (queue.length > 0) {
    var node = queue.shift();
    order.push(node);
    graph[node].forEach(function (next) {
      if (!visited[next]) {
        visited[next] = true;
        queue.push(next);
      }
    });
  }
  return order;
}

console.log(bfs(0));
